import { DatabaseSync } from "node:sqlite";
import fs from "node:fs";
import path from "node:path";
import crypto from "node:crypto";

export type PollOption = { id: string; text: string; votes: number };
export type Poll = {
  id: string;
  question: string;
  totalVotes: number;
  options: PollOption[];
};

type PollRow = { id: string; question: string; created_at: number };
type OptionRow = {
  id: string;
  poll_id: string;
  text: string;
  votes: number;
  position: number;
};

let dbInstance: DatabaseSync | null = null;

function getDb(): DatabaseSync {
  if (dbInstance) return dbInstance;

  const dataDir = path.join(process.cwd(), "data");
  fs.mkdirSync(dataDir, { recursive: true });
  const dbPath = path.join(dataDir, "polls.db");

  const db = new DatabaseSync(dbPath);
  db.exec("PRAGMA journal_mode = WAL;");
  db.exec("PRAGMA foreign_keys = ON;");
  db.exec(`
    CREATE TABLE IF NOT EXISTS polls (
      id TEXT PRIMARY KEY,
      question TEXT NOT NULL,
      created_at INTEGER NOT NULL
    );
  `);
  db.exec(`
    CREATE TABLE IF NOT EXISTS options (
      id TEXT PRIMARY KEY,
      poll_id TEXT NOT NULL,
      text TEXT NOT NULL,
      votes INTEGER NOT NULL DEFAULT 0,
      position INTEGER NOT NULL
    );
  `);
  db.exec(`
    CREATE TABLE IF NOT EXISTS poll_votes (
      poll_id TEXT NOT NULL,
      client_id TEXT NOT NULL,
      option_id TEXT NOT NULL,
      PRIMARY KEY (poll_id, client_id)
    );
  `);

  dbInstance = db;
  return db;
}

function rowsToPoll(pollRow: PollRow, optionRows: OptionRow[]): Poll {
  const options = optionRows.map((o) => ({
    id: o.id,
    text: o.text,
    votes: o.votes,
  }));
  const totalVotes = options.reduce((sum, o) => sum + o.votes, 0);
  return { id: pollRow.id, question: pollRow.question, totalVotes, options };
}

export function createPoll(question: string, optionTexts: string[]): Poll {
  const db = getDb();
  const id = crypto.randomUUID();
  const now = Date.now();

  db.exec("BEGIN");
  try {
    db.prepare(
      "INSERT INTO polls (id, question, created_at) VALUES (?, ?, ?)",
    ).run(id, question, now);

    const insertOption = db.prepare(
      "INSERT INTO options (id, poll_id, text, votes, position) VALUES (?, ?, ?, 0, ?)",
    );
    optionTexts.forEach((text, index) => {
      insertOption.run(crypto.randomUUID(), id, text, index);
    });

    db.exec("COMMIT");
  } catch (err) {
    db.exec("ROLLBACK");
    throw err;
  }

  return getPollById(id)!;
}

export function getPollById(id: string): Poll | null {
  const db = getDb();
  const pollRow = db.prepare("SELECT * FROM polls WHERE id = ?").get(id) as
    | PollRow
    | undefined;
  if (!pollRow) return null;

  const optionRows = db
    .prepare("SELECT * FROM options WHERE poll_id = ? ORDER BY position ASC")
    .all(id) as OptionRow[];

  return rowsToPoll(pollRow, optionRows);
}

export function listPolls(): Poll[] {
  const db = getDb();
  const pollRows = db
    .prepare("SELECT * FROM polls ORDER BY created_at DESC")
    .all() as PollRow[];

  return pollRows.map((pollRow) => {
    const optionRows = db
      .prepare(
        "SELECT * FROM options WHERE poll_id = ? ORDER BY position ASC",
      )
      .all(pollRow.id) as OptionRow[];
    return rowsToPoll(pollRow, optionRows);
  });
}

export type VoteResult =
  | { ok: true; poll: Poll }
  | {
      ok: false;
      reason: "poll_not_found" | "option_not_found" | "already_voted";
    };

export function voteOnPoll(
  pollId: string,
  optionId: string,
  clientId: string,
): VoteResult {
  const db = getDb();

  const pollRow = db.prepare("SELECT * FROM polls WHERE id = ?").get(pollId) as
    | PollRow
    | undefined;
  if (!pollRow) return { ok: false, reason: "poll_not_found" };

  const optionRow = db
    .prepare("SELECT * FROM options WHERE id = ? AND poll_id = ?")
    .get(optionId, pollId) as OptionRow | undefined;
  if (!optionRow) return { ok: false, reason: "option_not_found" };

  db.exec("BEGIN IMMEDIATE");
  try {
    const existingVote = db
      .prepare(
        "SELECT 1 as found FROM poll_votes WHERE poll_id = ? AND client_id = ?",
      )
      .get(pollId, clientId);

    if (existingVote) {
      db.exec("ROLLBACK");
      return { ok: false, reason: "already_voted" };
    }

    db.prepare(
      "INSERT INTO poll_votes (poll_id, client_id, option_id) VALUES (?, ?, ?)",
    ).run(pollId, clientId, optionId);
    db.prepare("UPDATE options SET votes = votes + 1 WHERE id = ?").run(
      optionId,
    );

    db.exec("COMMIT");
  } catch (err) {
    db.exec("ROLLBACK");
    throw err;
  }

  return { ok: true, poll: getPollById(pollId)! };
}

export const CLIENT_COOKIE_NAME = "poll_client_id";

export function parseClientId(request: Request): string | null {
  const cookieHeader = request.headers.get("cookie");
  if (!cookieHeader) return null;

  const parts = cookieHeader.split(";");
  for (const part of parts) {
    const eqIndex = part.indexOf("=");
    if (eqIndex === -1) continue;
    const key = part.slice(0, eqIndex).trim();
    if (key === CLIENT_COOKIE_NAME) {
      const value = part.slice(eqIndex + 1).trim();
      try {
        return decodeURIComponent(value);
      } catch {
        return value;
      }
    }
  }
  return null;
}

const ONE_YEAR_SECONDS = 60 * 60 * 24 * 365;

export function buildClientIdSetCookie(clientId: string): string {
  return `${CLIENT_COOKIE_NAME}=${encodeURIComponent(
    clientId,
  )}; Path=/; Max-Age=${ONE_YEAR_SECONDS}; SameSite=Lax`;
}

import { createFileRoute } from "@tanstack/react-router";
import { createPoll } from "../lib/db";

export const Route = createFileRoute("/api/polls")({
  server: {
    handlers: {
      POST: async ({ request }) => {
        let body: unknown;
        try {
          body = await request.json();
        } catch {
          return Response.json(
            { error: "Request body must be valid JSON." },
            { status: 400 },
          );
        }

        const question =
          typeof (body as any)?.question === "string"
            ? (body as any).question.trim()
            : "";

        const rawOptions = Array.isArray((body as any)?.options)
          ? (body as any).options
          : [];

        const options = rawOptions
          .filter((o: unknown): o is string => typeof o === "string")
          .map((o: string) => o.trim())
          .filter((o: string) => o.length > 0);

        if (!question || options.length < 2) {
          return Response.json(
            {
              error:
                "A question and at least two non-empty options are required.",
            },
            { status: 400 },
          );
        }

        const poll = createPoll(question, options);
        return Response.json(poll, { status: 201 });
      },
    },
  },
});

import { createFileRoute } from "@tanstack/react-router";
import { getPollById } from "../lib/db";

export const Route = createFileRoute("/api/polls/$id")({
  server: {
    handlers: {
      GET: async ({ params }) => {
        const poll = getPollById(params.id);
        if (!poll) {
          return Response.json({ error: "Poll not found." }, { status: 404 });
        }
        return Response.json(poll, { status: 200 });
      },
    },
  },
});

import { createFileRoute } from "@tanstack/react-router";
import crypto from "node:crypto";
import { voteOnPoll } from "../lib/db";
import { buildClientIdSetCookie, parseClientId } from "../lib/cookies";

export const Route = createFileRoute("/api/polls/$id/vote")({
  server: {
    handlers: {
      POST: async ({ request, params }) => {
        let body: unknown;
        try {
          body = await request.json();
        } catch {
          return Response.json(
            { error: "Request body must be valid JSON." },
            { status: 400 },
          );
        }

        const optionId =
          typeof (body as any)?.optionId === "string"
            ? (body as any).optionId
            : "";

        if (!optionId) {
          return Response.json(
            { error: "optionId is required." },
            { status: 400 },
          );
        }

        const clientId = parseClientId(request) ?? crypto.randomUUID();

        const result = voteOnPoll(params.id, optionId, clientId);

        if (!result.ok) {
          if (
            result.reason === "poll_not_found" ||
            result.reason === "option_not_found"
          ) {
            return Response.json(
              { error: "Poll or option not found." },
              { status: 404 },
            );
          }

          // already_voted
          const headers = new Headers({ "Content-Type": "application/json" });
          headers.append("Set-Cookie", buildClientIdSetCookie(clientId));
          return new Response(
            JSON.stringify({
              error: "You have already voted on this poll.",
            }),
            { status: 409, headers },
          );
        }

        const headers = new Headers({ "Content-Type": "application/json" });
        headers.append("Set-Cookie", buildClientIdSetCookie(clientId));
        return new Response(JSON.stringify(result.poll), {
          status: 200,
          headers,
        });
      },
    },
  },
});

import { createFileRoute, Link, useRouter } from "@tanstack/react-router";
import { createServerFn } from "@tanstack/react-start";
import { useState } from "react";
import { listPolls } from "../lib/db";

const fetchPolls = createServerFn({ method: "GET" }).handler(() => {
  return listPolls();
});

export const Route = createFileRoute("/")({
  component: HomePage,
  loader: async () => await fetchPolls(),
});

function HomePage() {
  const polls = Route.useLoaderData();
  const router = useRouter();

  const [question, setQuestion] = useState("");
  const [options, setOptions] = useState(["", ""]);
  const [error, setError] = useState<string | null>(null);
  const [submitting, setSubmitting] = useState(false);

  const updateOption = (index: number, value: string) => {
    setOptions((prev) => prev.map((o, i) => (i === index ? value : o)));
  };

  const addOption = () => setOptions((prev) => [...prev, ""]);

  const removeOption = (index: number) => {
    setOptions((prev) => prev.filter((_, i) => i !== index));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    setSubmitting(true);
    try {
      const res = await fetch("/api/polls", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ question, options }),
      });
      const data = await res.json();
      if (!res.ok) {
        setError(data.error || "Failed to create poll.");
        return;
      }
      setQuestion("");
      setOptions(["", ""]);
      router.navigate({ to: "/poll/$id", params: { id: data.id } });
    } catch {
      setError("Network error. Please try again.");
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <div style={{ maxWidth: 640, margin: "2rem auto", fontFamily: "sans-serif" }}>
      <h1>Polls</h1>

      <section style={{ marginBottom: "2rem" }}>
        <h2>Create a new poll</h2>
        <form onSubmit={handleSubmit}>
          <div style={{ marginBottom: "0.5rem" }}>
            <input
              type="text"
              placeholder="Question"
              value={question}
              onChange={(e) => setQuestion(e.target.value)}
              style={{ width: "100%", padding: "0.5rem", boxSizing: "border-box" }}
            />
          </div>
          {options.map((opt, i) => (
            <div key={i} style={{ marginBottom: "0.5rem", display: "flex", gap: "0.5rem" }}>
              <input
                type="text"
                placeholder={`Option ${i + 1}`}
                value={opt}
                onChange={(e) => updateOption(i, e.target.value)}
                style={{ flex: 1, padding: "0.5rem", boxSizing: "border-box" }}
              />
              {options.length > 2 && (
                <button type="button" onClick={() => removeOption(i)}>
                  Remove
                </button>
              )}
            </div>
          ))}
          <div style={{ marginTop: "0.5rem" }}>
            <button type="button" onClick={addOption} style={{ marginRight: "0.5rem" }}>
              Add option
            </button>
            <button type="submit" disabled={submitting}>
              {submitting ? "Creating..." : "Create poll"}
            </button>
          </div>
          {error && <p style={{ color: "red" }}>{error}</p>}
        </form>
      </section>

      <section>
        <h2>Existing polls</h2>
        {polls.length === 0 && <p>No polls yet. Create the first one above!</p>}
        <ul>
          {polls.map((poll) => (
            <li key={poll.id} style={{ marginBottom: "0.25rem" }}>
              <Link to="/poll/$id" params={{ id: poll.id }}>
                {poll.question}
              </Link>{" "}
              ({poll.totalVotes} votes)
            </li>
          ))}
        </ul>
      </section>
    </div>
  );
}

import { createFileRoute, notFound, Link } from "@tanstack/react-router";
import { createServerFn } from "@tanstack/react-start";
import { useCallback, useEffect, useState } from "react";
import { getPollById, type Poll } from "../lib/db";

const fetchPollById = createServerFn({ method: "GET" })
  .validator((id: string) => id)
  .handler(({ data: id }) => {
    return getPollById(id);
  });

export const Route = createFileRoute("/poll/$id")({
  component: PollPage,
  loader: async ({ params }) => {
    const poll = await fetchPollById({ data: params.id });
    if (!poll) {
      throw notFound();
    }
    return poll;
  },
  notFoundComponent: () => (
    <div style={{ maxWidth: 640, margin: "2rem auto", fontFamily: "sans-serif" }}>
      <p>
        <Link to="/">&larr; Back to all polls</Link>
      </p>
      <h1>Poll not found</h1>
    </div>
  ),
});

const POLL_INTERVAL_MS = 1000;

function PollPage() {
  const initialPoll = Route.useLoaderData();
  const { id } = Route.useParams();

  const [poll, setPoll] = useState<Poll>(initialPoll);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    setPoll(initialPoll);
  }, [initialPoll]);

  useEffect(() => {
    let cancelled = false;

    const tick = async () => {
      try {
        const res = await fetch(`/api/polls/${id}`);
        if (!cancelled && res.ok) {
          const data = (await res.json()) as Poll;
          setPoll(data);
        }
      } catch {
        // ignore transient network errors; we'll retry on the next tick
      }
    };

    const interval = setInterval(tick, POLL_INTERVAL_MS);
    return () => {
      cancelled = true;
      clearInterval(interval);
    };
  }, [id]);

  const handleVote = useCallback(
    async (optionId: string) => {
      setError(null);
      try {
        const res = await fetch(`/api/polls/${id}/vote`, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ optionId }),
        });

        if (res.status === 409) {
          const data = await res.json().catch(() => ({}));
          setError(data.error || "You have already voted on this poll.");
          return;
        }

        if (!res.ok) {
          const data = await res.json().catch(() => ({}));
          setError(data.error || "Something went wrong. Please try again.");
          return;
        }

        const data = (await res.json()) as Poll;
        setPoll(data);
      } catch {
        setError("Network error. Please try again.");
      }
    },
    [id],
  );

  const total = poll.totalVotes;

  return (
    <div style={{ maxWidth: 640, margin: "2rem auto", fontFamily: "sans-serif" }}>
      <p>
        <Link to="/">&larr; Back to all polls</Link>
      </p>
      <h1>{poll.question}</h1>
      <p data-testid="total-votes">Total votes: {total}</p>

      {error && (
        <p data-testid="vote-error" style={{ color: "red", fontWeight: "bold" }}>
          {error}
        </p>
      )}

      <ul style={{ listStyle: "none", padding: 0 }}>
        {poll.options.map((option) => {
          const percent = total === 0 ? 0 : Math.round((option.votes / total) * 100);
          return (
            <li key={option.id} style={{ marginBottom: "1rem" }}>
              <div style={{ display: "flex", alignItems: "center", gap: "0.5rem" }}>
                <button
                  type="button"
                  data-testid={`vote-${option.id}`}
                  onClick={() => handleVote(option.id)}
                  style={{ padding: "0.5rem 1rem" }}
                >
                  Vote: {option.text}
                </button>
                <span data-testid={`count-${option.id}`}>{option.votes} votes</span>
                <span data-testid={`percent-${option.id}`}>{percent}%</span>
              </div>
              <div
                style={{
                  background: "#eee",
                  height: 8,
                  borderRadius: 4,
                  overflow: "hidden",
                  marginTop: 4,
                }}
              >
                <div
                  style={{
                    width: `${percent}%`,
                    background: "#4caf50",
                    height: "100%",
                  }}
                />
              </div>
            </li>
          );
        })}
      </ul>
    </div>
  );
}

